ALTER TABLE "community_assets" ADD COLUMN "storage_provider" text;--> statement-breakpoint
ALTER TABLE "community_assets" ADD COLUMN "storage_bucket" text;--> statement-breakpoint
ALTER TABLE "community_assets" ADD COLUMN "storage_key" text;--> statement-breakpoint
ALTER TABLE "community_assets" ADD COLUMN "lifecycle_version" integer;--> statement-breakpoint
CREATE TABLE "asset_storage_objects" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"provider" text NOT NULL,"bucket" text NOT NULL,"object_key" text NOT NULL,"state" text DEFAULT 'pending' NOT NULL,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"retired_at" timestamp with time zone,CONSTRAINT "asset_storage_objects_identity_unique" UNIQUE("provider","bucket","object_key"),CONSTRAINT "asset_storage_objects_state_check" CHECK ("state" IN ('pending','active','deleting','deleted','failed')),CONSTRAINT "asset_storage_objects_key_check" CHECK ("provider" ~ '^[a-z][a-z0-9_-]{1,31}$' AND "bucket" ~ '^[a-z0-9][a-z0-9._-]*$' AND "object_key" ~ '^[A-Za-z0-9._/-]+$' AND "object_key" !~ '(^|/)\.{1,2}(/|$)'));--> statement-breakpoint
CREATE TABLE "asset_upload_attempts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"asset_id" uuid NOT NULL,"user_id" uuid NOT NULL,"object_id" uuid NOT NULL,"ready_object_id" uuid NOT NULL,"expected_size" integer NOT NULL,"content_type" text NOT NULL,"state" text DEFAULT 'reserved' NOT NULL,"fence_token" integer DEFAULT 0 NOT NULL,"expires_at" timestamp with time zone NOT NULL,"verification_digest" text,"created_at" timestamp with time zone DEFAULT now() NOT NULL,"verified_at" timestamp with time zone,CONSTRAINT "asset_upload_attempts_asset_unique" UNIQUE("asset_id"),CONSTRAINT "asset_upload_attempts_size_check" CHECK ("expected_size" >= 0),CONSTRAINT "asset_upload_attempts_state_check" CHECK ("state" IN ('reserved','uploaded','verified','promoting','ready','failed','expired','deleting','deleted')),CONSTRAINT "asset_upload_attempts_fence_check" CHECK ("fence_token" >= 0));--> statement-breakpoint
CREATE TABLE "asset_lifecycle_jobs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"object_id" uuid NOT NULL,"attempt_id" uuid,"kind" text NOT NULL,"idempotency_key" text NOT NULL,"state" text DEFAULT 'pending' NOT NULL,"attempts" integer DEFAULT 0 NOT NULL,"fence_token" integer DEFAULT 0 NOT NULL,"lease_token" uuid,"leased_until" timestamp with time zone,"available_at" timestamp with time zone DEFAULT now() NOT NULL,"completed_at" timestamp with time zone,"created_at" timestamp with time zone DEFAULT now() NOT NULL,CONSTRAINT "asset_lifecycle_jobs_idempotency_unique" UNIQUE("idempotency_key"),CONSTRAINT "asset_lifecycle_jobs_kind_check" CHECK ("kind" IN ('promotion','reconcile','cleanup')),CONSTRAINT "asset_lifecycle_jobs_state_check" CHECK ("state" IN ('pending','leased','complete','failed')),CONSTRAINT "asset_lifecycle_jobs_lease_check" CHECK (("state" = 'leased') = ("lease_token" IS NOT NULL AND "leased_until" IS NOT NULL)),CONSTRAINT "asset_lifecycle_jobs_fence_check" CHECK ("fence_token" >= 0));--> statement-breakpoint
CREATE INDEX "asset_lifecycle_jobs_poll_idx" ON "asset_lifecycle_jobs" USING btree ("state","available_at");
